function toolbar({search=false,searchPlaceholder="Search by name…",status=[],project=false,client=false,assessment=false,assessmentType=false,clientType=false,platform=false,framework=false,artifactFormat=false,buildType=false,severity=false,verification=false,remediation=false,template=false,extra=""}={}){const f=filters[filterKey()]||{};let controls="";if(search)controls+=`<label class="filter-field search-filter"><span>Search</span><div class="search-box">${icon("search")}<input name="q" placeholder="${e(searchPlaceholder)}" aria-label="${e(searchPlaceholder.replace(/…$/,""))}" value="${e(f.q||"")}" maxlength="200"></div></label>`;if(status.length)controls+=filterSelect("status","Status",status.map(value=>[value,pretty(value)]),f.status,"All statuses");if(clientType)controls+=filterSelect("client_type","Client type",[["company","Company"],["individual","Individual"]],f.client_type,"All client types");if(project)controls+=filterSelect("project_id","Project",references.projects.map(p=>[p.id,p.name]),f.project_id,"All projects");if(client)controls+=filterSelect("client_id","Client",references.clients.map(c=>[c.id,c.name]),f.client_id,"All clients");if(assessment)controls+=filterSelect("assessment_id","Assessment",(references.assessments||[]).map(a=>[a.id,a.name]),f.assessment_id,"All assessments");if(platform)controls+=filterSelect("platform","Platform",[["android","Android"],["ios","iOS"]],f.platform,"All platforms");if(framework)controls+=filterSelect("framework","Framework",[["native","Native"],["flutter","Flutter"],["react_native","React Native"],["other","Other"],["unknown","Unknown"]],f.framework,"All frameworks");if(artifactFormat)controls+=filterSelect("artifact_format","Artifact format",[["apk","APK"],["aab","AAB"],["ipa","IPA"]],f.artifact_format,"All formats");if(buildType)controls+=filterSelect("build_type","Build type",[["debug","Debug"],["release","Release"],["unknown","Unknown"]],f.build_type,"All build types");if(assessmentType)controls+=filterSelect("assessment_type","Assessment type",[["static","Static APK"],["dynamic","Dynamic testing"],["api","API security"],["full","Full assessment"]],f.assessment_type,"All assessment types");if(severity)controls+=filterSelect("severity","Severity",["critical","high","medium","low","info"].map(value=>[value,pretty(value)]),f.severity,"All severities");if(verification)controls+=filterSelect("verification_status","Verification",[["unreviewed","Unreviewed"],["confirmed","Confirmed"],["false_positive","False positive"],["needs_more_evidence","Needs more evidence"]],f.verification_status,"All verification states");if(remediation)controls+=filterSelect("remediation_status","Remediation",[["open","Open"],["in_progress","In progress"],["fixed","Fixed"],["accepted_risk","Accepted risk"],["retest_required","Retest required"]],f.remediation_status,"All remediation states");if(template)controls+=filterSelect("template","Report template",[["executive","Executive"],["technical","Technical"],["combined","Combined"]],f.template,"All templates");return filterPanel(controls+extra,f);}
export function metricCount(source,key){const value=source?.[key];return Number.isSafeInteger(value)&&value>=0?value.toLocaleString():"—";}
export function kpiCards(items){return `<div class="kpi-grid">${items.map(([label,value,foot,ico,tone])=>`<section class="kpi tone-${e(tone)}"><div class="kpi-icon">${icon(ico)}</div><div class="kpi-label">${e(label)}</div><div class="kpi-value">${e(value)}</div><div class="kpi-foot">${e(foot)}</div></section>`).join("")}</div>`;}
function applyFilterForm(form,{preserveFocus=false}={}){const key=filterKey(),values=Object.fromEntries(new FormData(form));if(["audit","overview"].includes(key)&&values.date_from&&values.date_to&&values.date_from>values.date_to){toast("From date must be on or before the To date.");return Promise.resolve();}for(const pageKey of Object.keys(filters))if(pageKey.startsWith(`${key}:`))delete filters[pageKey];filters[key]=Object.fromEntries(Object.entries(values).filter(([,value])=>String(value).trim()!==""));filters[key].offset=0;const active=document.activeElement,name=preserveFocus&&form.contains(active)?active.name:null,start=name&&typeof active.selectionStart==="number"?active.selectionStart:null,end=name&&typeof active.selectionEnd==="number"?active.selectionEnd:null;return navigate({keepTab:true}).then(()=>{if(!name)return;const field=document.getElementById("filter-form")?.elements.namedItem(name);if(!field)return;field.focus();if(start!==null&&typeof field.setSelectionRange==="function")field.setSelectionRange(start,end);});}
async function all(path,signal){let offset=0,result=[];while(offset<=10000){const response=await api(`${path}${path.includes("?")?"&":"?"}limit=100&offset=${offset}`,{signal});result.push(...response.items);if(result.length>=response.total)return result;offset+=100;}throw new Error("This workspace has too many records for this selector. Narrow the request using the API.");}
async function directoryMetrics({clientIds=[],projectIds=[]},signal){const query=new URLSearchParams();for(const id of clientIds)query.append("client_ids",id);for(const id of projectIds)query.append("project_ids",id);if(!query.size)return {clients:[],projects:[]};return api(`/directory-metrics?${query}`,{signal});}
async function loadReferences(signal,clients=false){const requests=[all("/projects",signal)];if(clients)requests.push(all("/clients",signal));const [p,c]=await Promise.all(requests);references.projects=p;if(c)references.clients=c;}
const projectName=(id)=>references.projects.find(p=>p.id===id)?.name||"Accessible project";
const clientName=(id)=>references.clients.find(p=>p.id===id)?.name||"Client";
async function navigate({keepTab=false}={}){
  if(!me)return;clearRefresh();controller?.abort();controller=new AbortController();const signal=controller.signal;const version=++renderVersion;route=parseRoute(location.hash);currentRecord=null;if(!keepTab)tab="overview";shell();
  try { const html=await renderPage(signal);if(version!==renderVersion||signal.aborted||!me)return;document.getElementById("page-content").innerHTML=html;document.title=`${nav.find(x=>x[0]===(route.page==="api-executions"?"api":route.page))?.[2]||"Workspace"} · DroidShield`; }
  catch(error){ if(error.name==="AbortError"||version!==renderVersion||!me)return;document.getElementById("page-content").innerHTML=pageHeader("We couldn't load this page","Your workspace data is protected. Retry when the connection is available.")+notice(errorText(error),"error")+btn("refresh","Try again","refresh"); }
}
function errorText(error){return `${error.message}${error.requestId?` Request ID: ${error.requestId}`:""}`;}
async function renderPage(signal){
  if(route.page==="overview")return overviewPage(signal);
  if(route.page==="clients")return route.id?clientPage(signal):clientsPage(signal);
  if(route.page==="projects")return route.id?projectPage(signal):projectsPage(signal);
  if(route.page==="assessments")return route.id?assessmentPage(signal):assessmentsPage(signal);
  if(route.page==="apk")return apkPage(signal);
  if(route.page==="findings")return findingsPage(signal);
  if(route.page==="dynamic")return dynamicPage(signal);
  if(route.page==="api"||route.page==="api-executions")return apiSecurityPage(signal);
  if(route.page==="methodology")return methodologyPage(signal);
  if(route.page==="retesting")return retestingPage(signal);
  if(route.page==="reports")return reportsPage(signal);
  if(route.page==="audit")return auditPage(signal);
  if(route.page==="users")return usersPage(signal);
  return settingsPage(signal);
}
export function assessmentWorkflowLabel(assessment) {
  if(assessment.status==="cancelled")return "Workflow cancelled";
  if(assessment.execution_mode==="analyst_record"||assessment.assessment_type==="full")return "Manual engagement";
  if(assessment.assessment_type==="api")return "HTTPS API baseline";
  if(assessment.assessment_type==="dynamic")return "Android lab";
  return `${pretty(assessment.engine||"manifest")} analysis`;
}
export function dynamicDeviceLabel(value){return value==="not-launched"?"Not launched":value||"—";}
function assessmentRows(items){return items.map(a=>`<tr><td><div class="row-identity"><div class="app-icon">${icon("phone")}</div><div>${link("assessments",a.id,a.name)}<span class="subtext">${e(projectName(a.project_id))}</span></div></div></td><td>${e(pretty(a.assessment_type))}<span class="subtext">${e(assessmentWorkflowLabel(a))}</span></td><td>${tag(a.status)}</td><td>${e(date(a.updated_at))}</td><td>${viewAction("assessments",a.id)}</td></tr>`);}
const overviewActivityRoutes={assessment:"assessments",client:"clients",project:"projects",finding:"findings",report:"reports",retest:"retesting",dynamic_session:"dynamic",api_target:"api",api_execution:"api"};
export function overviewActivityMarkup(events){
  const rows=Array.isArray(events)?events:[];
  if(!rows.length)return empty("No recent activity","Project and assessment events will appear here as work is recorded.","",true);
  return `<div class="card-body activity-feed" role="list" aria-label="Recent project activity">${rows.map(event=>{const resourceType=String(event.resource_type||"resource"),resourceId=String(event.resource_id||""),resourceRoute=overviewActivityRoutes[resourceType];const resourceLabel=/^[a-f0-9-]{36}$/i.test(resourceId)?`${pretty(resourceType)} · ${resourceId.slice(0,8)}`:pretty(resourceType);const resource=resourceRoute&&/^[a-f0-9-]{36}$/i.test(resourceId)?link(resourceRoute,resourceId,resourceLabel):e(resourceLabel);const actor=event.actor_id?`User ${String(event.actor_id).slice(0,8)}`:"System";return `<div class="activity-row" role="listitem"><div><strong>${e(pretty(String(event.action||"activity").replace(/[._]/g," ")))}</strong><p>${e(actor)} · ${e(date(event.timestamp))}</p><p>${resource} ${tag(event.result||"success")}</p></div></div>`;}).join("")}</div>`;
}
export function overviewPendingActionsMarkup(summary){
  const counts=summary&&typeof summary==="object"?summary:{};
  const total=metricCount(counts,"total");
  const queues=[["Assessment review","Independent review of completed assessments","assessment_reviews","assessments"],["Report approval","Review required before report release","report_reviews","reports"],["Retest review","Independent decision on remediation evidence","retest_reviews","retesting"]];
  const upToDate=counts.total===0;
  return `<div class="card-body"><div class="posture"><div class="posture-ring"><strong>${e(total)}</strong><span>Waiting</span></div><div><h3>${upToDate?"You're up to date":"Review actions"}</h3><p>${upToDate?"No assessment, report or retest reviews are waiting.":"These persisted records need an independent review decision."}</p></div></div><div class="selection-list">${queues.map(([label,description,key,page])=>`<div class="selection-row"><div><strong>${e(label)}</strong><p>${e(description)}</p></div><div class="inline-actions"><span class="pill-count">${e(metricCount(counts,key))}</span>${link(page,null,"Open queue →","details-link")}</div></div>`).join("")}</div></div>`;
}
const trendSeverityLevels=["critical","high","medium","low","info"];
export function riskTrendMarkup(points,selectedDays=30,overdueCount=0){
  const days=(Array.isArray(points)?points:[]).filter(point=>{
    const raw=String(point?.date||"");
    const timestamp=Date.parse(`${raw}T00:00:00Z`);
    return /^\d{4}-\d{2}-\d{2}$/.test(raw)&&Number.isFinite(timestamp)&&new Date(timestamp).toISOString().slice(0,10)===raw;
  }).map(point=>{
    const counts=Object.fromEntries(trendSeverityLevels.map(level=>[level,Number.isSafeInteger(point[level])&&point[level]>=0?point[level]:0]));
    return {date:String(point.date),counts,total:trendSeverityLevels.reduce((sum,level)=>sum+counts[level],0)};
  });
  const peak=Math.max(1,...days.map(day=>day.total));
  const total=days.reduce((sum,day)=>sum+day.total,0);
  const count=Number.isSafeInteger(overdueCount)&&overdueCount>=0?overdueCount:"—";
  const interval=Math.max(1,Math.ceil(days.length/7));
  const windowDays=[7,30,90].includes(Number(selectedDays))?Number(selectedDays):30;
  const chartDescription=`Daily counts for the last ${windowDays} days. ${total.toLocaleString()} currently confirmed and unresolved findings in this date range. Severity is shown by color; detailed values are available in the daily data table.`;
  const bars=days.map((day,index)=>{
    const label=new Intl.DateTimeFormat(undefined,{month:"short",day:"numeric",timeZone:"UTC"}).format(new Date(`${day.date}T00:00:00Z`));
    const segments=trendSeverityLevels.filter(level=>day.counts[level]>0).map(level=>`<span class="risk-segment ${level}" style="height:${Math.max(0.6,day.counts[level]/peak*100)}%" title="${e(pretty(level))}: ${e(day.counts[level])}"></span>`).join("");
    const showLabel=index%interval===0||index===days.length-1;
    return `<div class="risk-day" title="${e(day.date)} · ${e(day.total)} findings"><div class="risk-stack">${segments}</div><span class="risk-day-label">${showLabel?e(label):""}</span></div>`;
  }).join("");
  const legend=trendSeverityLevels.map(level=>`<span class="risk-legend-item"><i class="risk-legend-swatch ${level}" aria-hidden="true"></i>${e(pretty(level))}</span>`).join("");
  const detailRows=days.map(day=>`<tr><th scope="row">${e(day.date)}</th>${trendSeverityLevels.map(level=>`<td>${e(day.counts[level])}</td>`).join("")}<td><strong>${e(day.total)}</strong></td></tr>`).join("");
  return `<div class="card-body risk-trend-body"><div class="risk-trend-summary"><div><strong>${e(total.toLocaleString())}</strong><span>Currently open findings in this window</span></div><div class="overdue-summary"><strong>${e(count)}</strong><span>Overdue retests</span></div></div>${days.length?`<figure class="risk-trend-figure"><figcaption>Confirmed, unresolved findings by creation date and severity</figcaption><p class="risk-trend-description" id="risk-trend-description">${e(chartDescription)}</p><div class="risk-chart-scroll" role="region" tabindex="0" aria-label="Scrollable risk trend chart" aria-describedby="risk-trend-description"><div class="risk-chart-bars" aria-hidden="true">${bars}</div></div><div class="risk-legend" aria-label="Severity legend">${legend}</div></figure><details class="risk-trend-details"><summary>View daily data</summary><div class="table-wrap"><table><caption class="visually-hidden">Daily confirmed unresolved findings by severity</caption><thead><tr><th scope="col">Date</th>${trendSeverityLevels.map(level=>`<th scope="col">${e(pretty(level))}</th>`).join("")}<th scope="col">Total</th></tr></thead><tbody>${detailRows}</tbody></table></div></details>`:empty("No trend data available","The API did not return daily risk data for this window.","",true)}<p class="severity-caption">The chart groups findings by creation date and current status, so it is not a historical snapshot. Overdue retests count confirmed findings marked for retesting with an explicit due date in the past.</p></div>`;
}
