  if(result.frida){const f=result.frida;const apis=[["filesystem_open","Native filesystem open"],["socket_connect","Native socket connect"],["dns_lookup","Native DNS lookup"]];sections+=`<section class="result-tabs-content" aria-label="Frida observation"><h3>Frida API observation</h3>${detailList([["Frida version",f.version],["Observation window",`${safeCount(f.observation_seconds)} seconds`]])}${table(["Built-in API observation","Installed hook","Observed calls"],apis.map(([id,label])=>`<tr><td>${e(label)}</td><td>${Array.isArray(f.hooked_apis)&&f.hooked_apis.includes(id)?"Yes":"No"}</td><td>${e(safeCount(f.counters?.[id]))}</td></tr>`))}<p class="severity-caption">Native counters cover this bounded launch only. They retain no arguments, return values, paths, addresses or credentials. An observed call does not establish unsafe use.</p></section>`;}
  if(result.traffic){const t=result.traffic;sections+=`<section class="result-tabs-content" aria-label="Controlled proxy observation"><h3>Controlled proxy observation</h3>${detailList([["Requests forwarded",safeCount(t.requests_forwarded)],["Requests blocked",safeCount(t.blocked_requests)],["TLS failures",safeCount(t.tls_failures)],["Response bytes",safeCount(t.response_bytes)]])}${table(["Approved target","Method","HTTP status","TLS version","Response bytes"],(Array.isArray(t.observations)?t.observations:[]).map(o=>`<tr><td>Target ${Number.isSafeInteger(o.target_index)&&o.target_index>=0?o.target_index+1:"—"}</td><td>${e(o.method)}</td><td>${e(o.status_code)}</td><td>${e(o.tls_version)}</td><td>${e(safeCount(o.response_bytes))}</td></tr>`),"No forwarded requests observed","Only exact approved GET/HEAD endpoints can be forwarded. The application may not send traffic during this observation.")}<p class="severity-caption">Target numbers refer to the session's submitted allowlist. Request and response bodies, query strings, headers and credentials are not retained. The app must trust the administrator's lab CA; certificate pinning is not bypassed.</p></section>`;}
  if(Array.isArray(result.limitations))sections+=`<section class="result-tabs-content"><h3>Coverage & limitations</h3><ul class="permissions-list">${result.limitations.map(text=>`<li>${e(text)}</li>`).join("")}</ul></section>`;

  return sections;
