  currentUsers=data.items;
  const roles=[["ADMIN","Administrator"],["SECURITY_ANALYST","Security Analyst"],["VIEWER","Viewer"]];
  const filtersMarkup=filterPanel(`${filterSelect("role","Workspace role",roles,f.role,"All roles")}${filterSelect("status","Account status",[["active","Active"],["disabled","Disabled"]],f.status,"All statuses")}`,f);
  const rows=data.items.map(user=>workspaceUserRow(user,{canManage:true,currentUserId:me.id}));
  return pageHeader("Team & Access","Manage workspace roles and account access with a clear audit trail.",btn("new-user","Add member","plus","primary"))+notice("New accounts start disabled. Set a password through the trusted local CLI before activating an account; passwords and session tokens are never shown here.","warning")+card("Workspace members",`${data.total.toLocaleString()} accounts`,filtersMarkup+table(["Name","Email","Role","Status","Created","Action"],rows,"No workspace members match","Add a member or adjust the role and status filters.")+pager(data,"Workspace user pages"));
