async function settingsPage(signal){
  const actions=admin()?btn("edit-workspace-settings","Edit settings","edit","primary"):"";
  let settingsMarkup;
  if(admin()){
    const settings=await api("/settings",{signal});currentWorkspaceSettings=settings;
    settingsMarkup=workspaceSettingsMarkup(settings)+card("Protected integrations","Configuration presence only · not a readiness check",`<div class="card-body"><p class="muted">Connection strings, tokens, keys and certificate material stay server-side. Runtime health and device availability are checked separately before execution.</p>${workspaceSecretStatusMarkup(settings.secret_references)}</div>`);
  }else{
    currentWorkspaceSettings=null;
    settingsMarkup=card("Workspace preferences","Administrator-managed settings",`<div class="card-body">${notice("Workspace preference details are available to administrators. Your current access and assessment capabilities are shown below.","warning")}</div>`);
  }
  return pageHeader("Workspace settings","Manage workspace presentation defaults and review the capabilities available to your role.",actions)+settingsMarkup+`<div class="detail-grid">${card("Connection & access","Your current authenticated identity",`<div class="card-body">${detailList([["Name",me.full_name],["Email",me.email],["Role",pretty(me.role)],["Local time zone",Intl.DateTimeFormat().resolvedOptions().timeZone],["Workspace ID",me.workspace_id,true]])}<p class="severity-caption">Your session uses a protected cookie. Reloading restores access; signing out revokes the current session.</p>${btn("logout","Sign out","logout","small")}</div>`)}${card("Runtime configuration","Server-managed integrations and infrastructure",`<div class="card-body"><p class="muted">Analysis engine connections, private storage, retention policy and lab devices are configured by the server administrator.</p><p class="muted">Workspace preferences do not change scanner configuration or authorize a test.</p>${notice("The server checks your role, project scope and current authorization for every operation.")}</div>`)}</div>`+card("Analysis engines","Configured execution capabilities",`<div class="card-body">${await enginesMarkup(signal)}</div>`)+card("Service delivery workflow","From authorized testing to reviewed deliverables",`<div class="card-body"><p class="muted">Use Methodology to document manual Android/iOS tests, external tools and sanitized evidence. Verify findings independently, approve retest outcomes, then generate reviewed PDF/JSON deliverables.</p><p class="muted">The configured runtime worker supports dedicated Android emulators. Jailbroken iOS, Burp, Objection and device-specific checks run in the analyst's authorized external lab; their results remain explicitly manual.</p><p class="muted">Framework alignment and a report provide assessment evidence. They do not certify SOC 2, ISO 27001, HIPAA or PCI DSS compliance.</p></div>`);
}

