export function artifactFormat(filename) {
  const extension=/\.([a-z]+)$/i.exec(String(filename||""))?.[1].toLowerCase();
  if(!["apk","aab","ipa"].includes(extension))throw new Error("Choose an APK, AAB or IPA file.");
  return extension;
}
